function rect(x,y,w,h,c){ctx.fillStyle=c;ctx.fillRect(Math.round(x),Math.round(y),Math.round(w),Math.round(h))}
function text(s,x,y,size,color='#fff',align='center',font="'Press Start 2P'"){ctx.fillStyle=color;ctx.textAlign=align;ctx.font=`${size}px ${font}, monospace`;ctx.fillText(s,x,y)}
function background(){let g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'#1b1730');g.addColorStop(.58,'#36233b');g.addColorStop(1,'#11101f');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
// distant full moon and mountain silhouettes
ctx.fillStyle='#ffb66d';ctx.globalAlpha=.8;ctx.beginPath();ctx.arc(362,75,28,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;
rect(0,129,480,3,'#f29a7540');for(let i=0;i<7;i++){let x=i*82-20;ctx.fillStyle=i%2?'#241b32':'#2b1d34';ctx.beginPath();ctx.moveTo(x,170);ctx.lineTo(x+50,87+(i%3)*15);ctx.lineTo(x+118,170);ctx.fill()}
// temple structures
rect(24,92,7,82,'#21192c');rect(14,89,27,6,'#5d3448');rect(20,80,15,9,'#322037');rect(440,95,9,80,'#21192c');rect(430,91,29,6,'#613449');rect(437,82,16,9,'#322037');
for(let i=0;i<8;i++){let x=65+i*53;rect(x,132+(i%2)*8,3,44,'#20192d');rect(x-5,130+(i%2)*8,13,3,'#8e4a55');rect(x+5,137+(i%2)*8,2,26,'#d77961')}
// lanterns
for(const x of [72,408]){rect(x,75,2,23,'#9b604a');rect(x-4,83,10,12,'#ffc47b');rect(x-2,85,6,8,'#fff0ab');rect(x-5,82,12,2,'#633747')}
// stone floor
rect(0,177,480,93,'#282337');rect(0,177,480,3,'#c27b68');for(let i=0;i<12;i++){let x=i*42;rect(x,180,1,90,'#46364a');rect(x+18,180,1,90,'#362d41');rect(x,195+(i%2)*20,42,1,'#4c3a49')}
rect(0,221,480,3,'#ec9a67');ctx.fillStyle='#ffb56a';ctx.globalAlpha=.12;ctx.fillRect(0,223,480,9);ctx.globalAlpha=1;
// floating ember motes deterministic twinkle
for(let i=0;i<15;i++){let x=(i*67+elapsed*(i%3+1)*.25)%480,y=(i*37+elapsed*(i%2+1)*.12)%195;rect(x,y,1,1,i%3?'#ffc27877':'#f2707877')}}
function drawFighter(f){const pal=palettes[f.id],flip=f.face<0;ctx.save();ctx.translate(Math.round(f.x),Math.round(f.y));ctx.scale(flip?-1:1,1);let attackPose=f.attack>0?f.attackType:'',phase=Math.floor(f.walk)%4,air=f.y<FLOOR-2;let bob=air?0:phase===1?-1:0;
// shadow
ctx.fillStyle='#09091299';ctx.beginPath();ctx.ellipse(0,1,17,4,0,0,Math.PI*2);ctx.fill();
// leg poses
let kick=attackPose==='kick'&&f.attack>6;let legSwing=attackPose==='kick'?Math.max(0,10-f.attack)*1.3:0;
rect(-8, -21+bob,7,12,pal.pants);rect(2,-21+bob,7,12,pal.pants);
if(kick){rect(1,-21+bob,7,7,pal.pants);rect(8,-18+bob,13,5,pal.pants);rect(18,-19+bob,5,6,pal.trim)}else if(phase===1&&!air){rect(-9,-12,9,4,pal.pants);rect(1,-11,11,4,pal.pants)}else{rect(-10,-11,10,4,pal.pants);rect(2,-11,10,4,pal.pants)}
// torso + shoulder sash
rect(-9,-42+bob,18,22,pal.cloth);rect(-10,-40+bob,5,11,pal.trim);rect(5,-40+bob,5,11,pal.trim);rect(-8,-24+bob,16,3,pal.accent);rect(-2,-39+bob,4,17,'#17152a');
// head, hair, headband
rect(-7,-57+bob,14,14,pal.skin);rect(-8,-59+bob,16,6,pal.hair);rect(3,-52+bob,7,5,pal.hair);rect(3,-51+bob,3,2,'#f6ead3');rect(-8,-55+bob,17,2,pal.trim);rect(7,-56+bob,8,2,pal.accent);
// arms and fist
let punch=attackPose==='punch'&&f.attack>5,cast=attackPose==='special'&&f.attack>4,guard=f.block;
if(punch){rect(7,-39+bob,11,6,pal.skin);rect(16,-41+bob,8,8,pal.trim);rect(21,-40+bob,4,5,pal.skin)}else if(cast){rect(8,-40+bob,10,5,pal.skin);rect(15,-43+bob,9,10,pal.accent);rect(20,-41+bob,6,5,'#fff2ad')}else if(guard){rect(8,-44+bob,6,14,pal.skin);rect(7,-46+bob,8,7,pal.trim)}else{rect(8,-38+bob,5,12,pal.skin);rect(7,-28+bob,8,5,pal.trim)}
rect(-13,-39+bob,5,10,pal.skin);rect(-14,-30+bob,8,5,pal.trim);
// health flash outline
if(f.flash>0){rect(-15,-60+bob,30,62,'#fff7d777')}
ctx.restore();
if(f.block){rect(f.x-10,f.y-62,20,2,'#9dfbff');rect(f.x-9,f.y-61,18,1,'#fff')}}
function drawUI(){// health panels
rect(22,17,190,13,'#090911');rect(268,17,190,13,'#090911');let w1=186*p1.hp/100,w2=186*p2.hp/100;rect(24,19,w1,9,p1.hp<25?'#ed425f':'#52d9c7');rect(270+186-w2,19,w2,9,p2.hp<25?'#ed425f':'#f5a751');rect(22,15,190,2,'#f5e0bb');rect(268,15,190,2,'#f5e0bb');text('RIFT',24,13,7,'#65e8df','left');text('CLASH',456,13,7,'#ffb25d','right');text(String(Math.ceil(timer)).padStart(2,'0'),240,29,13,'#fff0cc');
for(let i=0;i<2;i++){let x=i===0?22:430;for(let j=0;j<2;j++){let win=roundWins[i]>j;rect(x+j*12,35,8,5,win?(i===0?'#62e8e1':'#ffb25d'):'#504356')}}
// chi meter
rect(22,44,74,4,'#0c0b15');rect(22,44,74*p1.energy/100,4,'#63ece4');rect(384,44,74,4,'#0c0b15');rect(458-74*p2.energy/100,44,74*p2.energy/100,4,'#ff9566');text('CHI',22,42,5,'#b5a3bf','left');text('CHI',458,42,5,'#b5a3bf','right')}
function drawParticles(){for(let p of particles){ctx.globalAlpha=clamp(p.life/15,0,1);rect(p.x,p.y,p.size,p.size,p.color)}ctx.globalAlpha=1;for(let b of projectiles){ctx.fillStyle=b.color+'55';ctx.fillRect(b.x-9,b.y-8,18,16);rect(b.x-5,b.y-5,10,10,b.color);rect(b.x-2,b.y-2,4,4,'#fff5b0')}}
function overlay(){if(state==='title'){ctx.fillStyle='#0d0b18bb';ctx.fillRect(0,0,W,H);text('RIFT//CLASH',240,76,21,'#ffe5b8');text('WHEN WORLDS COLLIDE',240,96,7,'#78e8df');
// two fighter silhouettes
rect(170,117,18,36,'#218d98');rect(174,100,14,18,'#e1a27d');rect(177,96,12,7,'#25213a');rect(292,117,18,36,'#c23b61');rect(292,100,14,18,'#d89276');rect(290,96,14,7,'#30202c');rect(189,128,26,6,'#62e8e1');rect(265,128,26,6,'#ffb35e');text('ARCADE DUEL · 1 PLAYER VS CPU',240,175,8,'#d2bfd3');text('PUNCH  ·  KICK  ·  CHI BLAST',240,195,7,'#ad9cb5');text('PRESS ENTER OR TAP TO FIGHT',240,232,8,'#ffe8b5');if(Math.floor(elapsed*2)%2===0)rect(120,241,240,1,'#f4bd6d')}
if(state==='paused'){ctx.fillStyle='#090814bb';ctx.fillRect(0,0,W,H);text('PAUSED',240,119,15,'#ffe7bc');text('PRESS ESCAPE TO RESUME',240,146,7,'#9cece2')}
if(state==='roundend'||state==='over'){ctx.fillStyle='#0908149c';ctx.fillRect(0,73,480,104);text(announcer,240,112,announcer.length>18?8:11,announcer.includes('PLAYER')?'#70ede0':'#ffc276');if(state==='roundend')text('NEXT ROUND',240,140,7,'#eee0c7');else{text(roundWins[0]>=2?'PLAYER 1 TAKES THE RIFT':'CPU CLAIMS THE RIFT',240,140,7,'#f3d9b2');text('ENTER TO REMATCH',240,231,8,'#fff0bf')}}}
function render(){ctx.save();if(shake>0)ctx.translate((Math.random()-.5)*shake,(Math.random()-.5)*shake);background();drawFighter(p1);drawFighter(p2);drawParticles();ctx.restore();if(state!=='title')drawUI();overlay();if(flash>0){ctx.globalAlpha=flash*.035;ctx.fillStyle='#fff';ctx.fillRect(0,0,W,H);ctx.globalAlpha=1}}
function frame(now){let dt=Math.min(2,(now-last)/16.67||1);last=now;if(state==='fight')update(dt);else elapsed+=dt;render();requestAnimationFrame(frame)}
requestAnimationFrame(frame);
