function updateFighter(f,op,dt){f.face=op.x>f.x?1:-1;f.cool=Math.max(0,f.cool-dt);f.stun=Math.max(0,f.stun-dt);f.flash=Math.max(0,f.flash-dt);f.comboTimer=Math.max(0,f.comboTimer-dt);if(!f.comboTimer)f.combo=0;
if(f.stun<=0){let left=f.id===0?down('a','arrowleft','left'):false,right=f.id===0?down('d','arrowright','right'):false,jump=f.id===0?down('w','arrowup','jump'):false;
if(f.id===1){const distance=Math.abs(op.x-f.x);left=distance>54&&f.x>op.x;right=distance>54&&f.x<op.x;jump=distance>95&&Math.random()<.002;if(distance<64&&f.cool===0&&f.attack===0&&Math.random()<.035)attack(f,Math.random()<.62?'punch':'kick');if(distance>120&&f.energy>=35&&f.cool===0&&Math.random()<.008)projectile(f)}
f.block=f.id===0?down('s','arrowdown','block'):Math.abs(op.x-f.x)<85&&Math.random()<.015;let move=(right?1:0)-(left?1:0);if(f.block)move=0;f.vx+=(move*1.35-f.vx)*.28;if(move)f.walk+=dt*(f.block?1:1.6);if(jump&&f.jumps<2&&f.vy===0){f.vy=-6.1;f.jumps++;sound(220,.05)}
if(f.id===0){if(down('j','punch'))attack(f,'punch');if(down('k','kick'))attack(f,'kick');if(down('l','special')&&f.energy>=35&&f.cool===0)projectile(f)}}else{f.block=false;f.vx*=.93}
if(f.attack>0){f.attack=Math.max(0,f.attack-dt);if(f.attack<(f.attackType==='punch'?9:f.attackType==='kick'?13:16)&&!f.attackHit){let reach=f.attackType==='kick'?45:38;if(Math.abs(op.x-f.x)<reach&&Math.abs(op.y-f.y)<40){hit(f,op,f.attackType);f.attackHit=true}}}
f.vy+=.27*dt;f.y+=f.vy*dt;f.x+=f.vx*dt;if(f.y>=FLOOR){f.y=FLOOR;f.vy=0;f.jumps=0}f.x=clamp(f.x,42,438);if(f.attack===0)f.attackHit=false}
