 <html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no"><meta name="theme-color" content="#100d1c"><title>RIFT//CLASH — Pixel Arena</title>
 <style>
 @import url('https://fonts.googleapis.com/css2?family=Press+Start+2P&family=Rajdhani:wght@500;600;700&display=swap');
 :root{color-scheme:dark;--ink:#f7ecd8;--gold:#ffca68;--cyan:#62e8e1;--pink:#ff5775}*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:#100d1c;color:var(--ink);font-family:'Rajdhani',sans-serif}body{display:grid;place-items:center;min-height:100svh;padding:18px;background:radial-gradient(ellipse at 50% 0%,#302044 0,#171426 42%,#0d0b15 100%);overflow:hidden}.shell{width:min(1120px,100%);position:relative}.topbar{display:flex;align-items:center;justify-content:space-between;margin:0 0 12px;color:#a89bb8;text-transform:uppercase;letter-spacing:.18em;font-size:12px;font-weight:700}.brand{color:#f5e8d0;font-family:'Press Start 2P',monospace;font-size:13px;letter-spacing:-.08em}.brand b{color:var(--pink)}.topbar .tag{display:flex;align-items:center;gap:8px}.live{width:7px;height:7px;border-radius:50%;background:#76efaf;box-shadow:0 0 10px #76efaf}.stage{position:relative;width:100%;aspect-ratio:16/9;overflow:hidden;border:1px solid #55435d;background:#171426;box-shadow:0 22px 80px #0009,0 0 0 5px #1c1725,0 0 50px #e1467020;touch-action:none}.stage canvas{width:100%;height:100%;display:block;image-rendering:pixelated;image-rendering:crisp-edges}.bottom{display:flex;align-items:center;justify-content:space-between;padding-top:13px;color:#ad9fb2;font-size:14px;letter-spacing:.05em}.keys{display:flex;align-items:center;gap:7px}.key{border:1px solid #54465c;background:#211b2b;color:#f5e8d0;padding:4px 8px;min-width:24px;text-align:center;font-size:12px;font-weight:700;box-shadow:0 2px #0a0910}.hint{color:#8f8396}.sound{border:1px solid #57475e;background:#211b2b;color:#dbcbdc;padding:7px 12px;font:700 11px 'Rajdhani',sans-serif;letter-spacing:.12em;text-transform:uppercase;cursor:pointer}.sound:hover{color:#fff;border-color:#c282b2}.touch-controls{display:none;position:absolute;inset:auto 0 10px;justify-content:space-between;padding:0 12px;pointer-events:none}.touch-group{display:flex;gap:8px;align-items:end;pointer-events:auto}.touch-btn{width:48px;height:4